from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

b_calls = 0

def b():
    global b_calls
    b_calls += 1
    return "B"

def a(b_val = Depends(b)):
    return f"A with {b_val}"

@app.get("/", dependencies=[Depends(b, scope="function")])
async def root(a_val = Depends(a)):
    return {"a": a_val}

client = TestClient(app)

def test_function_scope():
    global b_calls
    b_calls = 0
    response = client.get("/")
    assert response.status_code == 200
    # b should be called twice: once for the top-level dependency, once for a
    assert b_calls == 2, f"Expected 2 calls to b, got {b_calls}"

if __name__ == "__main__":
    try:
        test_function_scope()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
", "filepath": "/workspace/repro.py"}

